<?php
namespace App\Services\Staff;
use App\Models\StaffMember;use App\Models\StaffOtpChallenge;use App\Services\Auth\Registration\RegistrationOtpDeliveryService;use Illuminate\Support\Facades\Hash;use Illuminate\Validation\ValidationException;
class StaffOtpService {public function __construct(private readonly RegistrationOtpDeliveryService $delivery){} public function send(StaffMember $staff,string $channel):void{$target=$channel==='EMAIL'?$staff->email:$staff->whatsapp_number;if(blank($target))throw ValidationException::withMessages(['channel'=>'This staff profile has no '.$channel.' contact.']);$recent=StaffOtpChallenge::query()->where('staff_member_id',$staff->id)->where('channel',$channel)->latest('id')->first();if($recent&&$recent->sent_at->gt(now()->subMinute()))throw ValidationException::withMessages(['channel'=>'Wait one minute before requesting another code.']);$code=(string)random_int(100000,999999);StaffOtpChallenge::query()->create(['staff_member_id'=>$staff->id,'channel'=>$channel,'code_hash'=>Hash::make($code),'attempts'=>0,'sent_at'=>now(),'expires_at'=>now()->addMinutes(10)]);$channel==='EMAIL'?$this->delivery->sendEmail($target,$code):$this->delivery->sendWhatsApp($target,$code);} public function verify(StaffMember $staff,string $channel,string $code):void{$challenge=StaffOtpChallenge::query()->where('staff_member_id',$staff->id)->where('channel',$channel)->latest('id')->first();if(!$challenge||!$challenge->isUsable()||!Hash::check($code,$challenge->code_hash)){if($challenge)$challenge->increment('attempts');throw ValidationException::withMessages(['code'=>'The verification code is invalid or expired.']);}$challenge->update(['verified_at'=>now()]);$staff->forceFill($channel==='EMAIL'?['email_verified_at'=>now()]:['whatsapp_verified_at'=>now()])->save();}}
